/* Shared phoneme recordings: pure speech sounds used by Sound Safari, Letter Post Office, Robot Talk,
   Potion Spells and Chunk Kitchen. Robot Talk plays these in sequence for "c… a… t", so no segmented
   word needs its own recording. */
const PHONEMES = [
  ["s", "/s/", "Hold it: sss. No vowel after it (not 'suh')."], ["a", "/a/", "Short a as in 'ant'."],
  ["t", "/t/", "Short, whispered tap of the tongue. Not 'tuh'."], ["p", "/p/", "Short puff of air. Not 'puh'."],
  ["i", "/i/", "Short i as in 'insect'."], ["n", "/n/", "Hold it: nnn."], ["m", "/m/", "Hold it: mmm."],
  ["d", "/d/", "Short and voiced. Keep the 'uh' as small as possible."], ["g", "/g/", "Short and voiced, as in 'go'. Not 'guh'."],
  ["o", "/o/", "Short o as in 'octopus' (British)."], ["c", "/k/", "Short, whispered. Same sound as k and ck: record once, reuse for k and ck."],
  ["e", "/e/", "Short e as in 'egg'."], ["u", "/u/", "Short u as in 'up'."], ["r", "/r/", "Hold it: rrr. Not 'ruh'."],
  ["h", "/h/", "A breathy 'h', no vowel."], ["b", "/b/", "Short and voiced. Not 'buh'."], ["f", "/f/", "Hold it: fff."],
  ["l", "/l/", "Hold it: lll."], ["j", "/j/", "Short, as in 'jam'."], ["v", "/v/", "Hold it: vvv."],
  ["w", "/w/", "Short, lips rounded, as in 'wet'. Not 'wuh'."], ["x", "/ks/", "Two sounds together: ks."],
  ["y", "/y/", "Short, as in 'yes'."], ["z", "/z/", "Hold it: zzz."], ["qu", "/kw/", "kw, as in 'queen'."],
  ["sh", "/sh/", "Hold it: shhh."], ["ch", "/ch/", "Short, as in 'chip'."], ["th-unvoiced", "/th/", "As in 'thin'. Hold it, no voice."],
  ["th-voiced", "/th/", "As in 'this'. Hold it, with voice."], ["ng", "/ng/", "As at the end of 'sing'. Hold it."],
];

